package com.fintrack.khmtomnenh.company.service; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.company.dto.CompanyDto; import com.fintrack.khmtomnenh.company.entity.Company; import com.fintrack.khmtomnenh.company.repository.CompanyRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class CompanyService {private final CompanyRepository repo; public List<Company> list(Auth owner){return repo.findByOwner(owner);} public Company get(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Company not found"));} @Transactional public Company create(CompanyDto d,Auth o){return repo.save(Company.builder().owner(o).name(d.name().trim()).description(d.description()).email(d.email()).phone(d.phone()).address(d.address()).country(d.country().trim()).city(d.city().trim()).build());} @Transactional public Company update(Long id,CompanyDto d,Auth o){Company c=owned(id,o);c.setName(d.name().trim());c.setDescription(d.description());c.setEmail(d.email());c.setPhone(d.phone());c.setAddress(d.address());c.setCountry(d.country().trim());c.setCity(d.city().trim());return c;} @Transactional public void delete(Long id,Auth o){repo.delete(owned(id,o));} private Company owned(Long id,Auth o){Company c=get(id);if(!c.getOwner().getId().equals(o.getId()))throw new org.springframework.security.access.AccessDeniedException("Not company owner");return c;} }
